import java.util.*;
import java.util.function.*;

public class Main {
    static class AppConfig {
        Service service() { return new Service(); }
        Audit audit() { return new Audit(service()); }
    }
    static class Service { static int n = 0; int id = ++n; }
    static class Audit { Service s; Audit(Service s) { this.s = s; } }

    static class Container {
        Map<String, Object> singletons = new HashMap<>();
        Object getSingleton(String name, Supplier<Object> factory) {
            return singletons.computeIfAbsent(name, k -> factory.get());
        }
    }

    // 模拟 CGLIB：生成子类覆盖 @Bean 方法，强制走容器单例缓存
    static class AppConfig$$CGLIB extends AppConfig {
        final Container c;
        AppConfig$$CGLIB(Container c) { this.c = c; }
        @Override Service service() { return (Service) c.getSingleton("service", super::service); }
        @Override Audit audit() { return (Audit) c.getSingleton("audit", super::audit); }
    }

    public static void main(String[] args) {
        Container c = new Container();
        AppConfig cfg = new AppConfig$$CGLIB(c);
        Service s1 = cfg.service();
        Service s2 = cfg.service();
        Audit au = cfg.audit();
        System.out.println("direct calls same: " + (s1 == s2));
        System.out.println("internal call same: " + (au.s == s1));
        System.out.println("total Service instances: " + Service.n);
    }
}
